-- Real product photos in Explore. Beta only: brand rows must be removed or permissioned before public release
-- (update public.explore_outfits set published=false where photo_url is not null).
alter table public.explore_outfits
  add column photo_url text check(photo_url is null or photo_url ~ '^https://cdn\.shopify\.com/[^ ]+$'),
  add column price_label text not null default '';
alter table public.library_items
  add column explore_photo_url text check(explore_photo_url is null or explore_photo_url ~ '^https://cdn\.shopify\.com/[^ ]+$');

create or replace function public.save_explore(outfit_id text) returns uuid language plpgsql security definer set search_path='' as $$
declare result uuid; outfit public.explore_outfits;
begin
  if auth.uid() is null then raise exception 'Sign in to save'; end if;
  select * into outfit from public.explore_outfits where id=outfit_id and published;
  if not found then raise exception 'Outfit unavailable'; end if;
    values(auth.uid(),'inspiration',outfit.name,outfit.category,outfit.brand,outfit.tags,
      outfit.description || E'\nSource: ' || outfit.source_label,outfit.source_url,outfit.id,outfit.image,outfit.garment,outfit.photo_url)
    on conflict(owner_id,explore_id) where explore_id is not null do nothing returning id into result;
  if result is null then select id into result from public.library_items where owner_id=auth.uid() and explore_id=outfit_id; end if;
  return result;
end $$;
revoke all on function public.save_explore(text) from public,anon;
grant execute on function public.save_explore(text) to authenticated;

-- Hide the cartoon samples while real photos are available.
update public.explore_outfits set published=false where photo_url is null;

-- Generated by: node scripts/brand-explore-seed.cjs "Outfitters=outfitters.com.pk" "Breakout=breakout.com.pk"
on conflict(id) do update set name=excluded.name,photo_url=excluded.photo_url,price_label=excluded.price_label,source_url=excluded.source_url,published=true;
